import { useEffect, useState, useRef } from "react";
import { Badge } from "@/components/ui/badge";
import { Award, Users, Globe, Building } from "lucide-react";

const stats = [
  { 
    value: 2000, 
    suffix: "+", 
    label: "Projects Completed", 
    icon: Award,
    description: "Successfully delivered worldwide"
  },
  { 
    value: 70, 
    suffix: "+", 
    label: "Global Clients", 
    icon: Users,
    description: "Fortune 500 & industry leaders"
  },
  { 
    value: 8, 
    suffix: "", 
    label: "Countries", 
    icon: Globe,
    description: "International presence"
  },
  { 
    value: 18, 
    suffix: "+", 
    label: "Years Experience", 
    icon: Building,
    description: "Industry expertise since 2006"
  },
];

function AnimatedNumber({ value, suffix }: { value: number; suffix: string }) {
  const [count, setCount] = useState(0);
  const ref = useRef<HTMLDivElement>(null);
  const [hasAnimated, setHasAnimated] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasAnimated) {
          setHasAnimated(true);
          const duration = 2000;
          const steps = 60;
          const increment = value / steps;
          let current = 0;

          const timer = setInterval(() => {
            current += increment;
            if (current >= value) {
              setCount(value);
              clearInterval(timer);
            } else {
              setCount(Math.floor(current));
            }
          }, duration / steps);

          return () => clearInterval(timer);
        }
      },
      { threshold: 0.5 }
    );

    if (ref.current) {
      observer.observe(ref.current);
    }

    return () => observer.disconnect();
  }, [value, hasAnimated]);

  return (
    <div ref={ref} className="text-4xl sm:text-5xl font-bold text-foreground">
      {count}{suffix}
    </div>
  );
}

